// Whole source-host sample replacements and managed-file evidence.
// Normalize generated staging paths and only their derived filePath authority hashes together.
import fs from 'node:fs';import path from 'node:path';import os from 'node:os';import{createHash}from'node:crypto';import{pathToFileURL}from'node:url';
const base=new URL('.',pathToFileURL(process.argv[2]));const{McpHost}=await import(new URL('host.js',base));const{DeterministicLiveSimulator,LiveMutationNotDispatchedError}=await import(new URL('live.js',base));
const wave=Buffer.concat([Buffer.from('RIFF'),Buffer.from([16,0,0,0]),Buffer.from('WAVEfake-audio-bytes')]);
const scenarios=['normal','source-edit','staged-edit','staged-remove','expire','expire-sweep','epoch','device-identity','sample-state','missing-device','missing-prior','preview-unavailable','preview-read-fail','apply-before','apply-after','apply-refusal','apply-no-effect','apply-current-read','apply-preabort','undo-before','undo-after','undo-refusal','undo-no-effect','undo-current-read','undo-other-identity','undo-other-content','undo-epoch','finalize','uncertain-finalize','undo-asd'];
const cases=[];
async function make(label,kind,args,scenario='normal',files=[{name:'demo.wav',hex:wave.toString('hex')}]){
 const root=fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(),'host-import-'))),stage=path.join(root,'managed');fs.mkdirSync(stage);const revisions=new Map();for(const f of files){const file=path.join(root,f.name);fs.mkdirSync(path.dirname(file),{recursive:true});if(f.link)fs.symlinkSync(path.join(root,f.link),file);else if(f.directory)fs.mkdirSync(file,{recursive:true});else{fs.writeFileSync(file,Buffer.from(f.hex??'','hex'));if(f.size)fs.truncateSync(file,f.size);}}
 function clean(value){if(value===undefined)return null;value=structuredClone(value);if(value?.result?.content?.[0]?.text)try{value.result.content[0].text=JSON.parse(value.result.content[0].text)}catch{}function walk(v,key){if(typeof v==='string'){if(v.startsWith('simpler_'))return '$transaction';if(revisions.has(v))return revisions.get(v);const normalized=v.replaceAll(stage,'$stage').replaceAll(root,'$root').replace(/\$stage\/[^/"\\\s]+\//g,'$stage/$copy/');if(v.startsWith(stage+'/'))revisions.set(createHash('sha256').update(JSON.stringify({filePath:v})).digest('hex'),createHash('sha256').update(JSON.stringify({filePath:normalized})).digest('hex'));return normalized;}if(key==='expiresAt'&&v!==0)return '$time';if(key==='mtimeMs')return '$mtime';if(Array.isArray(v))return v.map(w=>walk(w));if(v&&typeof v==='object')return Object.fromEntries(Object.entries(v).map(([k,w])=>[k,walk(w,k)]));return v;}return walk(value);}
 function expand(v){if(typeof v==='string')return v.replaceAll('$root',root);if(Array.isArray(v))return v.map(expand);if(v&&typeof v==='object')return Object.fromEntries(Object.entries(v).map(([k,w])=>[k,expand(w)]));return v;}
 function filesNow(){const found=[];function visit(folder){for(const entry of fs.readdirSync(folder,{withFileTypes:true})){const file=path.join(folder,entry.name);if(entry.isDirectory())visit(file);else{const stat=fs.statSync(file);found.push({name:entry.name,size:stat.size,sha256:createHash('sha256').update(fs.readFileSync(file)).digest('hex'),mode:process.platform==='win32'?null:stat.mode&0o777});}}}visit(stage);found.sort((a,b)=>JSON.stringify(a).localeCompare(JSON.stringify(b)));return found;}
 const sim=new DeterministicLiveSimulator(),calls=[],cache=new Map();let fault='',fired=false,after=false;
 sim.state.scenes.push({ref:'scene:scene-2',objectIdentity:'simulator:scene:scene-2',name:'Scene 2',index:1});sim.state.tracks[0].clipSlots.push({ref:'clip-slot:track-1:1',parentRef:'track:track-1',objectIdentity:'simulator:clip-slot:track-1:1',sceneIndex:1,clipRef:null,empty:true});
 sim.state.tracks[0].takeLanes=[{ref:'take-lane:lane-1',parentRef:'track:track-1',objectIdentity:'simulator:take-lane:lane-1',name:'Lane',index:0,clips:[]}];
 sim.state.tracks[0].devices.push({ref:'device:simpler-1',parentRef:'track:track-1',name:'Simpler',kind:'instrument',className:'SimplerDevice',parameters:[],objectIdentity:'simulator:device:simpler-1',enabled:true,samplePath:'/old/a.wav'});const simpler=sim.state.tracks[0].devices.at(-1);if(scenario==='missing-device')sim.state.tracks[0].devices.pop();if(scenario==='missing-prior')delete simpler.samplePath;
 if(scenario==='missing-track')sim.state.tracks=[];if(scenario==='missing-slot')sim.state.tracks[0].clipSlots=[];if(scenario==='missing-scene')sim.state.scenes=[];if(scenario==='missing-identity')delete sim.state.tracks[0].objectIdentity;
 function ctx(c){return c?{deadline:c.deadlineMs!==undefined,...(c.idempotencyKey?{idempotencyKey:c.idempotencyKey}:{}),...(c.transactionId?{transactionId:c.transactionId}:{})}:null;}
 function status(){const s=sim.status();if(scenario==='preview-unavailable')s.connected=false;return s;}
 async function capture(method,args,context,work){const row={method,args:clean(args),context:clean(ctx(context))};calls.push(row);try{const value=await work();row.result=clean(value);return value;}catch(error){row.error={message:error.message,kind:error instanceof LiveMutationNotDispatchedError?'not-dispatched':'error'};throw error;}}
 function readFault(){if(scenario==='preview-read-fail'&&!fault)throw Error('injected authoritative read failure');if(!fired&&(fault.endsWith('current-read')||fault.endsWith('-read')&&after)){fired=true;throw Error('injected authoritative read failure');}}
 async function invoke(i,c){const key=JSON.stringify([c?.transactionId,c?.idempotencyKey,i]);if(cache.has(key))return structuredClone(cache.get(key));if(!fired&&['before','refusal'].some(s=>fault.endsWith(s))){fired=true;throw fault.endsWith('refusal')?new LiveMutationNotDispatchedError('mutation was not dispatched: ownership changed'):Error('injected operation failure');}const noEffect=!fired&&fault.endsWith('no-effect');const value=noEffect?{ok:true}:sim.invoke(i);if(noEffect)fired=true;else cache.set(key,structuredClone(value));after=true;if(!fired&&fault.endsWith('after')){fired=true;throw Error('injected operation failure');}if(!fired&&fault==='apply-invalid-identity'){fired=true;value.objectIdentity='';}if(!fired&&fault==='apply-invalid-file'){fired=true;value.filePath='';}return value;}
 const adapter={status,snapshot:()=>sim.snapshot(),get:r=>sim.get(r),invoke:i=>sim.invoke(i),subscribe:l=>sim.subscribe(l),reconnect:()=>sim.reconnect(),refreshStatusAsync:c=>capture('status',null,c,()=>status()),snapshotAsync:(c,r)=>capture('snapshot',r??null,c,()=>{readFault();return sim.snapshotAsync(c,r)}),discoverAsync:(r,c)=>capture('discover',r,c,()=>{readFault();return sim.discoverAsync(r,c)}),getAsync:(r,c)=>capture('get',r,c,()=>{readFault();if(fault==='apply-mapper')return undefined;return sim.get(r)}),invokeAsync:(i,c)=>capture('invoke',i,c,()=>invoke(i,c))};
 const host=new McpHost(adapter,{importStagingDir:stage}),steps=[];let txid;
 async function step(action,params,extra={}){const before=calls.length;const input={action,args:clean(params),status:status(),...extra};let result;try{const signal=new AbortController();if(extra.abort)signal.abort();if(action==='preview')result=await host.liveSimplerPreviewAsync(1,expand(params));else if(action==='project')result=await host.liveProjectImportAsync(1,expand(params));else if(action==='apply')result=await host.liveSimplerApplyAsync(1,{...params,transactionId:txid},signal.signal);else if(action==='undo')result=await host.liveUndoAsync(1,{...params,transactionId:txid},signal.signal);else if(action==='finalize')result=await host.liveRecoveryFinalizeAsync(1,{...params,transactionId:txid});}catch(error){result={throw:error.message};}if(action==='preview'){try{txid=JSON.parse(result.result.content[0].text).transactionId;}catch{}}const record=txid?host.clipLifecycleTransactions.get(txid):undefined;steps.push({...input,result:clean(result),record:clean(record),files:filesNow(),stageMode:process.platform==='win32'?null:fs.statSync(stage).mode&0o777,calls:calls.slice(before)});return result;}
 try{
  if(kind==='project'){if(scenario.startsWith('apply-'))fault=scenario;await step('project',args);}
  else{
   await step('preview',args);if(txid&&kind!=='preview'){
    const record=host.clipLifecycleTransactions.get(txid),staged=record.payload.filePath;
    if(scenario==='source-edit')fs.writeFileSync(path.join(root,'demo.wav'),Buffer.from('unauthorized changed source'));
    if(scenario==='staged-edit'){fs.chmodSync(staged,0o600);fs.writeFileSync(staged,Buffer.from('tampered bytes'));}
    if(scenario==='staged-remove')fs.unlinkSync(staged);
    if(scenario==='expire'||scenario==='expire-sweep')record.expiresAt=0;
    if(scenario==='device-identity')simpler.objectIdentity='manual';if(scenario==='sample-state')simpler.samplePath='/manual.wav';if(scenario==='epoch')sim.reconnect();if(scenario==='track-identity')sim.state.tracks[0].objectIdentity='manual';if(scenario==='slot-identity')sim.state.tracks[0].clipSlots[1].objectIdentity='manual';if(scenario==='scene-identity')sim.state.scenes[1].objectIdentity='manual';
    if(scenario==='occupied')sim.state.tracks[0].clipSlots[1].clipRef='clip:clip-1';
    const change=['source-edit','staged-edit','staged-remove','expire','expire-sweep'].includes(scenario)?scenario:undefined;
    if(scenario==='expire-sweep'){await step('preview',args,{change});}
    if(scenario.startsWith('apply-'))fault=scenario;if(scenario==='uncertain-finalize')fault='apply-after';
    for(const [index,key]of (scenario==='uncertain-finalize'?['apply-key']:['apply-key','other-key','apply-key']).entries())await step('apply',{confirmation:'apply',idempotencyKey:key},{...(index===0&&change&&scenario!=='expire-sweep'?{change}:{}),...(scenario==='apply-preabort'?{abort:true}:{})});
    fault='';fired=false;after=false;const latest=host.clipLifecycleTransactions.get(txid);const created=latest?.created?.ref;const clip=simpler;
    if(clip&&scenario==='undo-other-identity')clip.objectIdentity='manual';if(clip&&scenario==='undo-other-content')clip.samplePath='/manual.wav';if(scenario==='undo-epoch')sim.reconnect();if(clip&&scenario==='undo-already-absent'){for(const track of sim.state.tracks){track.clips=track.clips.filter(c=>c.ref!==created);for(const slot of track.clipSlots)if(slot.clipRef===created){slot.clipRef=null;slot.empty=true;}}}
    if(scenario==='undo-asd')fs.writeFileSync(staged+'.asd','analysis');
    if(scenario==='finalize'||scenario==='uncertain-finalize'){await step('finalize',{resolution:'accepted-current-state',confirmation:'finalize-recovery-record',evidence:{provenance:'test-operator',scope:'exact created clip and stopped transport'}});}
    else{if(scenario.startsWith('undo-')&&!['undo-other-identity','undo-other-content','undo-epoch','undo-already-absent'].includes(scenario))fault=scenario;for(const [index,key]of ['undo-key','other-undo-key','undo-key'].entries())await step('undo',{confirmation:'undo',idempotencyKey:key},{...(scenario==='undo-asd'&&index===0?{change:'staged-asd'}:{})});}
   }
  }
  cases.push({label,kind,files,steps});
 }finally{fs.rmSync(root,{recursive:true,force:true});}
}
const session={filePath:'$root/demo.wav',allowedRoot:'$root',deviceRef:'device:simpler-1'};
for(const scenario of scenarios)await make('simpler '+scenario,'workflow',session,scenario);
for(const args of [null,[],{},false,1,'x',{...session,extra:1},{...session,deviceRef:''},{...session,deviceRef:null},{...session,filePath:'demo.wav'},{...session,filePath:null},{...session,allowedRoot:''},{...session,filePath:'$root/missing.wav'}])await make('invalid '+JSON.stringify(args),'preview',args);
fs.writeFileSync(new URL('host-simpler-oracle.json',import.meta.url),JSON.stringify({cases}));console.log({cases:cases.length,steps:cases.reduce((n,c)=>n+c.steps.length,0)});
